#pragma once

#include <stdint.h>

/**
 * @file led_layout.h
 * @brief Physical layout of the star's LEDs.
 *
 * Logical LED index = position in the data chain: 0..65 are D201..D266
 * (front face, PCB top layer), 66..131 are D301..D366 (back face, bottom
 * layer). Coordinates are front-view millimetres with the origin at the star
 * centre, x right and y up. Both faces share the same XY positions.
 *
 * The table is generated by sw/tools/gen_led_layout.py; see
 * docs/led-layout.md for the bitmaps.
 */

#define LED_FACE_COUNT 66
#define LED_COUNT (2 * LED_FACE_COUNT)
#define LED_GRID_SIZE 32
#define LED_NONE 0xFF

/** Star tip radius in millimetres. */
#define LED_STAR_RADIUS_MM 110

enum led_face {
	LED_FACE_FRONT = 0,
	LED_FACE_BACK = 1,
};

enum led_group {
	LED_GROUP_OUTLINE = 0,
	LED_GROUP_INNER = 1,
};

struct led_info {
	uint8_t designator; /**< 1..66, e.g. 32 for D232/D332 */
	uint8_t face;       /**< enum led_face */
	int8_t x;           /**< mm, front view, origin at centre */
	int8_t y;           /**< mm, y up */
	uint8_t r;          /**< distance from centre, mm */
	uint8_t angle;      /**< 0..255 = 0..360 deg, 0 = right, CCW */
	uint8_t col;        /**< 0..31 bitmap column */
	uint8_t row;        /**< 0..31 bitmap row, 0 = top */
	uint8_t group;      /**< enum led_group */
	uint8_t point;      /**< 0..5 star point, clockwise */
	uint8_t step;       /**< position along the group, clockwise */
	uint8_t partner;    /**< logical index of the LED at the same XY on the other face */
};

extern const struct led_info led_layout[LED_COUNT];

/** Front-face logical index per bitmap cell, LED_NONE where empty. */
extern const uint8_t led_grid[LED_GRID_SIZE][LED_GRID_SIZE];

/**
 * @brief Logical index from side (1 = front, 2 = back) and designator index (1..66).
 * @return Logical index, or -1 if out of range.
 */
static inline int led_layout_index(int side, int designator)
{
	if (side < 1 || side > 2 || designator < 1 || designator > LED_FACE_COUNT) {
		return -1;
	}
	return (side - 1) * LED_FACE_COUNT + designator - 1;
}

/**
 * @brief Find the LED nearest to a front-view position.
 *
 * @param x_mm X coordinate in millimetres (any range).
 * @param y_mm Y coordinate in millimetres.
 * @param face Face to search.
 * @param max_dist_mm Maximum accepted distance.
 * @return Logical index, or -1 if no LED is within max_dist_mm.
 */
int led_layout_nearest(int x_mm, int y_mm, enum led_face face, int max_dist_mm);

/**
 * @brief Parse an LED name such as "D232" or a logical index "97".
 * @return Logical index, or -1 if invalid.
 */
int led_layout_parse(const char *name);
